// th18_s4_w04: TH18 v1.00a Stage 4 MainSub01 last group, st04.ecl.txt:893-905.
// Cir01 source: st04.ecl.txt:68-139. Movement source: 404/405 (ABS) + 422 (REL).
const TIME_LIMIT: int = 640;       // 120 opening buffer + 520 wave-local estimate
const SOURCE_ESTIMATE: int = 520;  // no source timer; see meta.toml notes
const TH18_RING_BALL2: int = 464;  // etSprite(0,7,2): type 7 RingBall2

// One Cir01. Source order is movement tick -> ECL, so the task reads F(k)
// and pre-arms the next source movement tick F(k+1) before wait(1).
async sub cir01() {
    set_invuln(65535);
    set_hurtbox(14fx);   // source setHurtbox(28,28); native circle uses half width
    set_hitbox(8fx);     // source setHitbox(16,16); native circle uses half width

    var rank: int = global(GVAR_RANK);
    var n: int = 15;
    var interval: int = 100;
    var spd: fx = 1.2fx;
    if rank == 1 { n = 25; interval = 80; spd = 1.8fx; }
    if rank == 2 { n = 30; interval = 70; spd = 1.8fx; }
    if rank == 3 { n = 42; interval = 70; spd = 2.3fx; }
    var shots: int = 1;   // diffI($A, 1, 3, 3, 3)
    if rank > 0 { shots = 3; }

    // etNew/etAim(0,3)/etSprite(0,7,2)/etCount/etAngle/etSpeed/etEx(ANIM a=1)
    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 2);
    sh_aim(0, 0);   // fixed-angle ring; alpha is randomized before each fire
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, spd, 0fx);
    sh_dist(0, -4fx*spd);   // ANIM a=1 birth retreat: position -= 4*velocity

    // 422 setter: C_rel=(0,0), theta=0, omega=2deg/frame, r=10, beta=ABS_ANGLE
    // (90deg after moveVel), s=0 => REL offset (10*cos(theta), 0). The setter
    // changes the weapon point on its own frame.
    var sx: fx = $self_x;
    var y: fx = $self_y;    // spawn y = -32
    var th: angle = 0deg;
    var f: int = 0;
    var next_fire: int = 81;   // source wait(80), then async first run next frame
    var shot: int = 0;
    move_to(0, sx + 10fx, y, EASE_LINEAR);

    loop {
        if f == next_fire && shot < shots {
            sh_angle(0, rand(65536) as angle, 0deg);
            sh_fire(0);
            shot = shot + 1;
            next_fire = next_fire + interval;
        }
        var nf: int = f + 1;
        var ny: fx = y;
        if nf <= 80 {
            ny = y + (4.4fx - 0.05fx*(nf as fx));  // 405 mode0: 4.4 -> 0.4
        } else {
            ny = y + 0.4fx;
        }
        var nth: angle = th + 2deg;
        var nx: fx = sx + 10fx*cos(nth);
        move_vel_xy(0, nx - (sx + 10fx*cos(th)), ny - y, EASE_LINEAR);
        y = ny;
        th = nth;
        f = nf;
        wait(1);
    }
}

async sub wave() {
    wait(120);  // opening buffer; the attack is active from here
    _ = spawn_enemy(100fx, -32fx, 1000, 0, 0, 0, cir01);
    _ = spawn_enemy(-100fx, -32fx, 1000, 0, 0, 0, cir01);
    wait(40);
    _ = spawn_enemy(120fx, -32fx, 1000, 0, 0, 0, cir01);
    _ = spawn_enemy(-120fx, -32fx, 1000, 0, 0, 0, cir01);
    wait(40);
    _ = spawn_enemy(140fx, -32fx, 1000, 0, 0, 0, cir01);
    _ = spawn_enemy(-140fx, -32fx, 1000, 0, 0, 0, cir01);
    wait(40);
    _ = spawn_enemy(160fx, -32fx, 1000, 0, 0, 0, cir01);
    _ = spawn_enemy(-160fx, -32fx, 1000, 0, 0, 0, cir01);
    wait(40);
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);   // control enemy only; real Cir01 keep source hitbox
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
